def for_info(self, info):
    type = info.get("type")
    if type == "nulldata":
        return self._script_tools.compile("OP_RETURN") + info.get("data")
    if type == "unknown":
        return info["script"]
    script_text = self._SCRIPT_LOOKUP[type](info)
    return self._script_tools.compile(script_text)

