def register_functions(self, lookup):
    for c, v in lookup:
        parse_f, stream_f = v
        self.parse_lookup[c] = parse_f
        self.stream_lookup[c] = stream_f

def match(self, c):
    if isinstance(c, Atom) and not isinstance(c, Operator):
        return {self._name: c}
    return False

def parse_struct(self, fmt, f):
    items = []
    i = 0
    while i < len(fmt):
        c = fmt[i]
        if c == "[":
            end = fmt.find("]", i)
            if end < 0:
                raise ValueError("no closing ] character")
            subfmt = fmt[i+1:end]
            count = self.array_count_parse_f(f)
            array = []
            for j in range(count):
                if len(subfmt) == 1:
                    array.append(self.parse_struct(subfmt, f)[0])
                else:
                    array.append(self.parse_struct(subfmt, f))
            items.append(tuple(array))
            i = end
        else:
            items.append(self.parse_lookup[c](f))
        i += 1
    return tuple(items)

def stream_struct(self, fmt, f, *args):
    for c, v in zip(fmt, args):
        self.stream_lookup[c](f, v)

def pack_struct(self, fmt, *args):
    b = io.BytesIO()
    self.stream_struct(fmt, b, *args)
    return b.getvalue()

def bignum_type_for_library(library):
    ULONG_FACTOR = 1 << (8 * ctypes.sizeof(ctypes.c_ulong))

    class BignumType(ctypes.Structure):
        """
        The structure that's manipulated by bn, the bignum library.
        struct bignum_st {
            BN_ULONG *d;    /* Pointer to an array of 'BN_BITS2' bit chunks. */
            int top;    /* Index of last used d +1. */
            /* The next are internal book keeping for bn_expand. */
            int dmax;    /* Size of the d array. */
            int neg;    /* one if the number is negative */
            int flags;
        };
        """

        _fields_ = [
            ('d', ctypes.POINTER(ctypes.c_ulong)),
            ('top', ctypes.c_int),
            ('dmax', ctypes.c_int),
            ('neg', ctypes.c_int),
            ('flags', ctypes.c_int),
        ]

        def __init__(self, n=0):
            "Create a BignumType from an int"
            negative = (n < 0)
            if negative:
                n = -n
            the_len = (n.bit_length() + 7)//8
            sign = b'\x80' if negative else b'\0'
            the_bytes = struct.pack(">L", the_len+1) + sign + to_bytes(n, the_len, "big")
            library.BN_mpi2bn(the_bytes, the_len + 5, self)

        def __del__(self):
            "Release memory used by native library"
            library.BN_clear_free(self)

        def __int__(self):
            "cast to int"
            return self.as_int()

        def to_int(self):
            "Return this bignum's value as a Python integer."
            value, factor = 0, 1
            for w in self.datawords():
                value += w * factor
                factor *= ULONG_FACTOR
            if self.neg:
                value = -value
            return value

        def datawords(self):
            "Yield the words in the little-endian data array."
            return (self.d[k] for k in range(self.top))

        def __repr__(self):
            return "BignumType(%d)" % self.to_int()
    return BignumType

def compile_push_data(self, data):
    # return bytes that causes the given data to be pushed onto the stack
    if data in self.const_encoder:
        return self.const_encoder.get(data)
    size = len(data)
    if size in self.sized_encoder:
        return self.sized_encoder.get(size)(data)
    for max_size, opcode, enc_f in self.variable_encoder:
        if size <= max_size:
            break
    return int2byte(opcode) + enc_f(len(data)) + data

def __mul__(self, e):
    """Multiply the generator by an integer. Uses the blinding factor."""
    return self.raw_mul(e + self._blinding_factor) + self._minus_blinding_factor_g

def __rmul__(self, e):
    """Multiply the generator by an integer."""
    return self.__mul__(e)

def __neg__(self):
    """Unary negation"""
    return self.__class__(self[0], self._curve.p()-self[1], self._curve)

def infinity(self):
