def read(self, N):
    d = self.f.read(N)
    if len(d) >= N:
        return d
    if self._next_file():
        d1 = d + self.f.read(N-len(d))
        return d1
    return b""

def broadcast_tx(self, tx):
    s = io.BytesIO()
    tx.stream(s)
    tx_as_hex = b2h(s.getvalue())
    data = urlencode(dict(tx=tx_as_hex)).encode("utf8")
    URL = self.api_domain + "/pushtx"
    try:
        d = urlopen(URL, data=data).read()
        return d
    except request.HTTPError as ex:
        try:
            d = ex.read()
            ex.message = d
        except Exception:
            pass
        raise ex

