        longest_chain = "longest chain %s to %s of size %d" % (start, finish, self.unlocked_length())
    else:
        longest_chain = "no unlocked elements"
    return "<BlockChain with %d locked elements and %s>" % (self.locked_length(), longest_chain)

def maximum_path(self, h, cache={}):
    v = self.trees_from_bottom.get(h)
    if v:
        return v
    h1 = h
    v = []
    while h1 is not None:
        v.append(h1)
        h1 = self.parent_lookup.get(h1)
    for i, h1 in enumerate(v):
        cache[h1] = v[i:]
    return v

def find_ancestral_path(self, h1, h2, path_cache={}):
    p1 = self.maximum_path(h1, path_cache)
    p2 = self.maximum_path(h2, path_cache)
    if p1[-1] != p2[-1]:
        return [], []

    shorter_len = min(len(p1), len(p2))
    i1 = len(p1) - shorter_len
    i2 = len(p2) - shorter_len
    while 1:
        if p1[i1] == p2[i2]:
            return p1[:i1+1], p2[:i2+1]
        i1 += 1
        i2 += 1

def _update_q(q, ops):
    # first, we meld out complimentary adds and removes
    while len(ops) > 0:
        op = ops[0]
        if op[0] != 'remove':
            break
        last = q.pop()
        if op[1:] != last[1:]:
            q.put_nowait(last)
            break
        ops = ops[1:]
    for op in ops:
        q.put_nowait(op)

