def OP_IF(self, the_bool, reverse_bool=False):
    if self.false_count > 0:
        self.false_count += 1
        return
    if reverse_bool:
        the_bool = not the_bool
    if the_bool:
        self.true_count += 1
    else:
        self.false_count = 1

def OP_ELSE(self):
    if self.false_count > 1:
        return
    if self.false_count == 1:
        self.false_count = 0
        self.true_count += 1
    else:
        if self.true_count == 0:
            return self.error_f("OP_ELSE without OP_IF")
        self.true_count -= 1
        self.false_count += 1

def make_op_checksig(constraints):
    def my_op_checksig(vm):

        def sighash_f(signature_type):
            return vm.signature_for_hash_type_f(signature_type, [], vm)

        t1 = vm.stack.pop()
        t2 = vm.stack.pop()
        t = Operator('SIGNATURES_CORRECT', [t1], [t2], sighash_f)
        constraints.append(Operator('IS_PUBKEY', t1))
        constraints.append(Operator('IS_SIGNATURE', t2))
        vm.stack.append(t)
    return my_op_checksig

def make_op_checkmultisig(constraints):
    def my_op_checkmultisig(vm):

        def sighash_f(signature_type):
            return vm.signature_for_hash_type_f(signature_type, [], vm)

        key_count = vm.IntStreamer.int_from_script_bytes(vm.stack.pop(), require_minimal=False)
        public_pair_blobs = []
        for i in range(key_count):
            constraints.append(Operator('IS_PUBKEY', vm.stack[-1]))
            public_pair_blobs.append(vm.stack.pop())
        signature_count = vm.IntStreamer.int_from_script_bytes(vm.stack.pop(), require_minimal=False)
        sig_blobs = []
        for i in range(signature_count):
            constraints.append(Operator('IS_SIGNATURE', vm.stack[-1]))
            sig_blobs.append(vm.stack.pop())
        t1 = vm.stack.pop()
        constraints.append(Operator('EQUAL', t1, b''))
        t = Operator('SIGNATURES_CORRECT', public_pair_blobs, sig_blobs, sighash_f)
        vm.stack.append(t)
    return my_op_checkmultisig

def my_op_checksig(vm):

    def sighash_f(signature_type):
        return vm.signature_for_hash_type_f(signature_type, [], vm)

    t1 = vm.stack.pop()
    t2 = vm.stack.pop()
    t = Operator('SIGNATURES_CORRECT', [t1], [t2], sighash_f)
    constraints.append(Operator('IS_PUBKEY', t1))
    constraints.append(Operator('IS_SIGNATURE', t2))
    vm.stack.append(t)

def make_traceback_f(constraints, int_for_opcode_f, reset_stack_f):

    TWEAKED_OPCODES = (
        ("OP_HASH160", make_op_hash160),
        ("OP_EQUALVERIFY", make_op_equalverify),
        ("OP_EQUAL", make_op_equal),
        ("OP_CHECKSIG", make_op_checksig),
        ("OP_CHECKMULTISIG", make_op_checkmultisig),
    )

    MY_OPCODES = {int_for_opcode_f(k): v(constraints) for k, v in TWEAKED_OPCODES}

    def prelaunch(vmc):
        if not vmc.is_solution_script:
            # reset stack
            vmc.stack = reset_stack_f(vmc.stack)

    def traceback_f(opcode, data, pc, vm):
        f = MY_OPCODES.get(opcode)
        if f is None:
            return
        stack_size = getattr(f, "stack_size", 0)
        if stack_size and all(not isinstance(v, Atom) for v in vm.stack[-stack_size:]):
            return
        return f

    def postscript(vmc):
        if not vmc.is_solution_script:
            if isinstance(vmc.stack[-1], Atom):
                constraints.append(vmc.stack[-1])
            vmc.stack = [vmc.VM_TRUE]

    traceback_f.prelaunch = prelaunch
    traceback_f.postscript = postscript
    return traceback_f

def prelaunch(vmc):
    if not vmc.is_solution_script:
        # reset stack
        vmc.stack = reset_stack_f(vmc.stack)

def traceback_f(opcode, data, pc, vm):
    f = MY_OPCODES.get(opcode)
    if f is None:
        return
    stack_size = getattr(f, "stack_size", 0)
    if stack_size and all(not isinstance(v, Atom) for v in vm.stack[-stack_size:]):
        return
    return f

def postscript(vmc):
    if not vmc.is_solution_script:
        if isinstance(vmc.stack[-1], Atom):
            constraints.append(vmc.stack[-1])
        vmc.stack = [vmc.VM_TRUE]

def make_variable_handler(dec_f, sized_values, min_size, non_minimal_data_handler):
    """
    Create a handler for a data opcode that returns literal data of a variable size
    that's fetched and decoded by the function dec_f.
    """
    sized_values = list(sized_values)

    def f(script, pc, verify_minimal_data=False):
        size, pc = dec_f(script, pc)
        data = bytes_as_hex(script[pc:pc+size])
        if len(data) < size:
            return pc+1, None
        if verify_minimal_data:
            if size in sized_values or size <= min_size:
                non_minimal_data_handler("not minimal push of data with size %d" % size)
        return pc+size, data
    return f

def constant_size_opcode_handler(script, pc, verify_minimal_data=False):
    pc += 1
    data = bytes_as_hex(script[pc:pc+size])
    if len(data) < size:
        return pc+1, None
    if verify_minimal_data and data in const_values:
        non_minimal_data_handler("not minimal push of %s" % repr(data))
    return pc+size, data

def f(script, pc, verify_minimal_data=False):
    size, pc = dec_f(script, pc)
    data = bytes_as_hex(script[pc:pc+size])
    if len(data) < size:
        return pc+1, None
    if verify_minimal_data:
        if size in sized_values or size <= min_size:
            non_minimal_data_handler("not minimal push of data with size %d" % size)
    return pc+size, data

def sighash_type_to_string(self, sighash_type):
    v = sighash_type
    flag_bit_list = []
    for flag_bit, flag_name in self.BIT_LIST:
        if v & flag_bit:
            v &= ~flag_bit
            flag_bit_list.append(flag_name)
    base_type = self.BASE_LOOKUP.get(v, "SIGHASH_UNKNOWN")
    return "".join([base_type] + [" | %s" % s for s in flag_bit_list])

def annotate_checksig(self, vmc, da):
    s = list(vmc.stack)
    try:
        self.annotate_pubkey(vmc.pop(), da)
        self.annotate_signature(vmc.pop(), da, vmc)
    except (IndexError, ValueError):
        pass
    vmc.stack = s

def annotate_checkmultisig(self, vmc, da):
    s = list(vmc.stack)
    try:
        key_count = vmc.pop_int()
        while key_count > 0:
            key_count -= 1
            self.annotate_pubkey(vmc.pop(), da)

        signature_count = vmc.pop_int()
        while signature_count > 0:
            signature_count -= 1
            self.annotate_signature(vmc.pop(), da, vmc)
    except IndexError:
        pass
    vmc.stack = s

def traceback_f(opcode, data, pc, vmc):
    if opcode in (self.OP_CHECKSIG, self.OP_CHECKSIGVERIFY):
        self.annotate_checksig(vmc, data_annotations)
    if opcode in (self.OP_CHECKMULTISIG, self.OP_CHECKMULTISIGVERIFY):
        self.annotate_checkmultisig(vmc, data_annotations)
    return

def instruction_for_opcode(self, opcode, data):
    if data is None or len(data) == 0:
        return self._script_tools.disassemble_for_opcode_data(opcode, data)
    b2h_data = b2h(data)
    if len(data) == 1:
        return "OP_%d" % byte2int(data)
    return "[PUSH_%s] %s" % (opcode, b2h_data)

def annotate_scripts(self, tx, tx_in_idx):
    "return list of pre_annotations, pc, opcode, instruction, post_annotations"
    # input_annotations_f, output_annotations_f = annotation_f_for_scripts(tx, tx_in_idx)

    data_annotations = collections.defaultdict(list)

    def traceback_f(opcode, data, pc, vmc):
        if opcode in (self.OP_CHECKSIG, self.OP_CHECKSIGVERIFY):
            self.annotate_checksig(vmc, data_annotations)
        if opcode in (self.OP_CHECKMULTISIG, self.OP_CHECKMULTISIGVERIFY):
            self.annotate_checkmultisig(vmc, data_annotations)
        return

    try:
        tx.check_solution(tx_in_idx, traceback_f=traceback_f)
    except ScriptError:
        pass

    r = []

    def traceback_f(opcode, data, pc, vmc):
        a0 = []
        if vmc.pc == 0:
            if vmc.is_solution_script:
                a0.append("--- SIGNATURE SCRIPT START")
            else:
                a0.append("--- PUBLIC KEY SCRIPT START")
        r.append((a0, vmc.pc, opcode, self.instruction_for_opcode(opcode, data), data_annotations[data]))

    try:
        tx.check_solution(tx_in_idx, traceback_f=traceback_f)
    except ScriptError:
        pass

    # the script may have ended early, so let's just double-check
    try:
        for idx, (opcode, data, pc, new_pc) in enumerate(itertools.chain(
            self._script_tools.get_opcodes(tx.unspents[tx_in_idx].script),
                self._script_tools.get_opcodes(tx.txs_in[tx_in_idx].script))):
            if idx >= len(r):
                r.append(([], pc, opcode, self.instruction_for_opcode(opcode, data), []))
    except IndexError:
        pass

    return r

def annotate_spendable(self, tx_class, spendable):
    txs_in = [tx_class.TxIn(b'1' * 32, 0)]
    fake_spend_tx = tx_class(1, txs_in, [])
    fake_spend_tx.set_unspents([spendable])
    return self.annotate_scripts(fake_spend_tx, 0)

def traceback_f(opcode, data, pc, vmc):
    a0 = []
    if vmc.pc == 0:
        if vmc.is_solution_script:
            a0.append("--- SIGNATURE SCRIPT START")
        else:
            a0.append("--- PUBLIC KEY SCRIPT START")
    r.append((a0, vmc.pc, opcode, self.instruction_for_opcode(opcode, data), data_annotations[data]))

def eval_script(self):
    if len(self.script) > self.MAX_SCRIPT_LENGTH:
        raise ScriptError("script too long", errno.SCRIPT_SIZE)

    f = getattr(self.traceback_f, "prelaunch", None)
    if f:
        f(self)

    while self.pc < len(self.script):
        self.eval_instruction()

    f = getattr(self.traceback_f, "postscript", None)
    if f:
        f(self)

    self.post_script_check()
    return self.stack

def eval_instruction(self):
    all_if_true = self.conditional_stack.all_if_true()

    # don't actually check for minimal data unless data will be pushed onto the stack
    verify_minimal_data = self.flags & VERIFY_MINIMALDATA and all_if_true
    opcode, data, pc, is_ok = self.ScriptStreamer.get_opcode(
        self.script, self.pc, verify_minimal_data=verify_minimal_data)
    if not is_ok:
        raise ScriptError("malformed data", errno.BAD_OPCODE)
    if data and len(data) > self.MAX_BLOB_LENGTH:
        raise ScriptError("pushing too much data onto stack", errno.PUSH_SIZE)

    if data is None:
        self.op_count += 1

    self.check_stack_size()

    f = self.INSTRUCTION_LOOKUP[opcode]
    if self.traceback_f:
        f = self.traceback_f(opcode, data, pc, self) or f

    if data is not None and all_if_true:
        self.stack.append(data)

    self.pc = pc

    if all_if_true or getattr(f, "outside_conditional", False):
        f(self)

    if self.op_count > self.MAX_OP_COUNT:
        raise ScriptError("script contains too many operations", errno.OP_COUNT)

def check_stack_size(self):
    if len(self.stack) + len(self.altstack) > self.MAX_STACK_SIZE:
        raise ScriptError("stack has > %d items" % self.MAX_STACK_SIZE, errno.STACK_SIZE)

def post_script_check(self):
    self.conditional_stack.check_final_state()
    self.check_stack_size()

def check_final_state(self):
    if self.false_count > 0 or self.true_count > 0:
        return self.error_f("missing ENDIF")

def OP_ENDIF(self):
    if self.false_count > 0:
        self.false_count -= 1
    else:
        if self.true_count == 0:
            return self.error_f("OP_ENDIF without OP_IF")
        self.true_count -= 1

def __init__(self, chain_code, depth=0, parent_fingerprint=b'\0\0\0\0', child_index=0,
             secret_exponent=None, public_pair=None):
    """Don't use this. Use a classmethod to generate from a string instead."""

    if [secret_exponent, public_pair].count(None) != 1:
        raise ValueError("must include exactly one of public_pair and secret_exponent")

    super(BIP32Node, self).__init__(
        secret_exponent=secret_exponent, public_pair=public_pair, is_compressed=True)

    if secret_exponent:
        self._secret_exponent_bytes = to_bytes_32(secret_exponent)

    if not isinstance(chain_code, bytes):
        raise TypeError("chain code must be bytes")
    if len(chain_code) != 32:
        raise ValueError("chain code wrong length")
    self._chain_code = chain_code
    self._depth = depth
    if len(parent_fingerprint) != 4:
        raise EncodingError("parent_fingerprint wrong length")
    self._parent_fingerprint = parent_fingerprint
    self._child_index = child_index
    self._subkey_cache = dict()

def ip_bin_to_ip4_addr(ip_bin):
    from pycoin.intbytes import iterbytes
    return "%d.%d.%d.%d" % tuple(iterbytes(ip_bin[-4:]))

def host(self):
    if self.ip_bin.startswith(IP4_HEADER):
        return ip_bin_to_ip4_addr(self.ip_bin[-4:])
    return ip_bin_to_ip6_addr(self.ip_bin)

def initial_key_to_master_key(initial_key):
    """
    initial_key:
        a hex string of length 32
    """
    b = initial_key.encode("utf8")
    orig_input = b
    for i in range(100000):
        b = hashlib.sha256(b + orig_input).digest()
    return from_bytes_32(b)

def __init__(self, initial_key=None, master_private_key=None, public_pair=None, master_public_key=None):
    if [initial_key, public_pair, master_private_key, master_public_key].count(None) != 3:
        raise ValueError(
            "exactly one of initial_key, master_private_key, master_public_key must be non-None")
    self._initial_key = initial_key

    if initial_key is not None:
        master_private_key = initial_key_to_master_key(initial_key)
    if master_public_key:
        public_pair = tuple(from_bytes_32(master_public_key[idx:idx+32]) for idx in (0, 32))
    super(ElectrumWallet, self).__init__(
        secret_exponent=master_private_key, public_pair=public_pair, is_compressed=False)

def from_master_secret(class_, master_secret):
    """Generate a Wallet from a master password."""
    I64 = hmac.HMAC(key=b"Bitcoin seed", msg=master_secret, digestmod=hashlib.sha512).digest()
    return class_(chain_code=I64[32:], secret_exponent=from_bytes_32(I64[:32]))

def deserialize(class_, blob):
    if len(blob) == 32:
        return class_(master_private_key=from_bytes_32(blob))
    if len(blob) == 64:
        return class_(master_public_key=blob)

def deserialize(class_, data):
    parent_fingerprint, child_index = struct.unpack(">4sL", data[5:13])
    d = dict(chain_code=data[13:45], depth=ord(data[4:5]), parent_fingerprint=parent_fingerprint,
             child_index=child_index)
    is_private = (data[45:46] == b'\0')
    if is_private:
        d["secret_exponent"] = from_bytes_32(data[46:])
    else:
        d["public_pair"] = sec_to_public_pair(data[45:], generator=class_._generator)
    return class_(**d)

def deserialize(class_, data):
    parent_fingerprint, child_index = struct.unpack(">4sL", data[5:13])
    d = dict(chain_code=data[13:45], depth=ord(data[4:5]), parent_fingerprint=parent_fingerprint,
             child_index=child_index)
    is_private = (data[45:46] == b'\0')
    if is_private:
        d["secret_exponent"] = from_bytes_32(data[46:])
    else:
        d["public_pair"] = sec_to_public_pair(data[45:], generator=class_._generator)
    return class_(**d)

def serialize(self):
    if self._secret_exponent:
        return to_bytes_32(self._secret_exponent)
    return self.master_public_key()

def secret_exponent(self):
    if self._secret_exponent is None and self._initial_key:
        self._secret_exponent = initial_key_to_master_key(b2h(self._initial_key))
    return self._secret_exponent

def public_copy(self):
    if self.secret_exponent() is None:
        return self
    return self.__class__(public_pair=self.public_pair())

def subkey(self, path):
    """
    path:
        of the form "K" where K is an integer index, or "K/N" where N is usually
        a 0 (deposit address) or 1 (change address)
    """
    t = path.split("/")
    if len(t) == 2:
        n, for_change = t
    else:
        n, = t
        for_change = 0
    b = (str(n) + ':' + str(for_change) + ':').encode("utf8") + self.master_public_key()
    offset = from_bytes_32(double_sha256(b))
    if self.secret_exponent():
        return self.__class__(
            master_private_key=((self.master_private_key() + offset) % self._generator.order())
        )
    p1 = offset * self._generator
    x, y = self.public_pair()
    p2 = self._generator.Point(x, y)
    p = p1 + p2
    return self.__class__(public_pair=p)

def subkeys(self, path):
    """
    A generalized form that can return multiple subkeys.
    """
    for _ in subpaths_for_path_range(path, hardening_chars="'pH"):
        yield self.subkey(_)

def subpaths_for_path_range(path_range, hardening_chars="'pH"):
    """
    Return an iterator of paths

        # examples:
        #   0/1H/0-4 => ['0/1H/0', '0/1H/1', '0/1H/2', '0/1H/3', '0/1H/4']
        #   0/2,5,9-11 => ['0/2', '0/5', '0/9', '0/10', '0/11']
        #   3H/2/5/15-20p => ['3H/2/5/15p', '3H/2/5/16p', '3H/2/5/17p', '3H/2/5/18p',
        #          '3H/2/5/19p', '3H/2/5/20p']
        #   5-6/7-8p,15/1-2 => ['5/7H/1', '5/7H/2', '5/8H/1', '5/8H/2',
        #         '5/15/1', '5/15/2', '6/7H/1', '6/7H/2', '6/8H/1', '6/8H/2', '6/15/1', '6/15/2']
    """
    if path_range == '':
        yield ''
        return

    def range_iterator(the_range):
        for r in the_range.split(","):
            is_hardened = r[-1] in hardening_chars
            hardened_char = hardening_chars[-1] if is_hardened else ''
            if is_hardened:
                r = r[:-1]
            if '-' in r:
                low, high = [int(x) for x in r.split("-", 1)]
                for t in range(low, high+1):
                    yield "%d%s" % (t, hardened_char)
            else:
                yield "%s%s" % (r, hardened_char)

    components = path_range.split("/")
    iterators = [range_iterator(c) for c in components]
    for v in itertools.product(*iterators):
        yield '/'.join(v)

def range_iterator(the_range):
    for r in the_range.split(","):
        is_hardened = r[-1] in hardening_chars
        hardened_char = hardening_chars[-1] if is_hardened else ''
        if is_hardened:
            r = r[:-1]
        if '-' in r:
            low, high = [int(x) for x in r.split("-", 1)]
            for t in range(low, high+1):
                yield "%d%s" % (t, hardened_char)
        else:
            yield "%s%s" % (r, hardened_char)

def path_for_hash160(self, hash160):
    SQL = "select fingerprint, path from HASH160 where hash160 = ?"
    c = self._exec_sql(SQL, hash160)
    r = c.fetchone()
    if r is not None:
        return r[0], r[1].decode("utf8")

def p2s_for_hash(self, hash160or256):
    SQL = "select script from P2S where hash160 = ? or hash256 = ?"
    c = self._exec_sql(SQL, hash160or256, hash160or256)
    r = c.fetchone()
    if r is not None:
        return r[0]

def get(self, hash160, default=None):
    v = self.p2s_for_hash(hash160)
    if v:
        return v

    if hash160 not in self._secret_exponent_cache:
        v = self.path_for_hash160(hash160)
        if v:
            fingerprint, path = v
            for key in self._secrets.get(fingerprint, []):
                subkey = key.subkey_for_path(path)
                self._add_key_to_cache(subkey)

    return self._secret_exponent_cache.get(hash160, default)

def interested_hashes(self):
    SQL = "select hash160 from HASH160"
    c = self._exec_sql(SQL)
    for r in c:
        yield r[0]
    SQL = "select hash160, hash256 from P2S"
    c = self._exec_sql(SQL)
    for r in c:
        yield r[0]
        yield r[1]

def override_network(self, override_network):
    blob = self.serialize()
    padded_blob = b"\0\0\0\0" + blob
    return override_network.keys.bip32_deserialize(padded_blob)

def serialize(self, as_private=None):
    """
    Yield a 74-byte binary blob corresponding to this node.
    You must add a 4-byte prefix before converting to base58.
    """
    if as_private is None:
        as_private = self.secret_exponent() is not None
    if self.secret_exponent() is None and as_private:
        raise PublicPrivateMismatchError("public key has no private parts")

    ba = bytearray()
    ba.extend([self._depth])
    ba.extend(self._parent_fingerprint + struct.pack(">L", self._child_index) + self._chain_code)
    if as_private:
        ba += b'\0' + self._secret_exponent_bytes
    else:
        ba += self.sec(is_compressed=True)
    return bytes(ba)

def hwif(self, as_private=False):
    """Yield a 111-byte string corresponding to this node."""
    return self._network.bip32_as_string(self.serialize(as_private=as_private), as_private=as_private)

def public_copy(self):
    """Yield the corresponding public node for this node."""
    d = dict(chain_code=self._chain_code, depth=self._depth,
             parent_fingerprint=self._parent_fingerprint,
             child_index=self._child_index, public_pair=self.public_pair())
    return self.__class__(**d)

def _subkey(self, i, is_hardened, as_private):
    if i < 0:
        raise ValueError("i can't be negative")
    if i >= 0x80000000:
        raise ValueError("subkey index 0x%x too large" % i)
    i &= 0x7fffffff
    if is_hardened:
        i |= 0x80000000

    d = dict(depth=self._depth+1, parent_fingerprint=self.fingerprint(), child_index=i)

    if self.secret_exponent() is None:
        if is_hardened:
            raise PublicPrivateMismatchError("can't derive a private key from a public key")
        d["public_pair"], chain_code = subkey_public_pair_chain_code_pair(
            self._generator, self.public_pair(), self._chain_code, i)
    else:
        d["secret_exponent"], chain_code = subkey_secret_exponent_chain_code_pair(
            self._generator, self.secret_exponent(), self._chain_code, i, is_hardened, self.public_pair())
    d["chain_code"] = chain_code
    key = self.__class__(**d)
    if not as_private:
        key = key.public_copy()
    return key

def children(self, max_level=50, start_index=0, include_hardened=True):
    for i in range(start_index, max_level+start_index+1):
        yield self.subkey(i)
        if include_hardened:
            yield self.subkey(i, is_hardened=True)

def verify_message(self, key_or_address, signature, message=None, msg_hash=None):
    """
    Take a signature, encoded in Base64, and verify it against a
    key object (which implies the public key),
    or a specific base58-encoded pubkey hash.
    """
    if isinstance(key_or_address, str):
        # they gave us a private key or a public key already loaded.
        key = self._network.parse.address(key_or_address)
    else:
        key = key_or_address

    try:
        msg_hash = self.hash_for_signing(message) if message is not None else msg_hash
        pair, is_compressed = self.pair_for_message_hash(signature, msg_hash)
    except EncodingError:
        return False
    return self.pair_matches_key(pair, key, is_compressed)

def _handle_checksig(self, vmc):
    s = list(vmc.stack)
    sec_blob = sig_blob = None
    sig_hash = 0
    try:
        sec_blob = vmc.pop()
        sig_blob = vmc.pop()
        try:
            sig_pair, sig_type = parse_signature_blob(sig_blob)
            sig_hash = vmc.signature_for_hash_type_f(sig_type, [sig_blob], vmc)
        except ValueError:
            pass
    except (IndexError, ValueError):
        pass

    return ([sec_blob], [(sig_blob, sig_hash)])

def _handle_checkmultisig(self, vmc):
    sec_blobs = []
    sig_blobs = []
    s = list(vmc.stack)
    try:
        key_count = vmc.pop_int()
        while key_count > 0:
            key_count -= 1
            sec_blobs.append(vmc.pop())

        signature_count = vmc.pop_int()
        while signature_count > 0:
            signature_count -= 1
            sig_blob = vmc.pop()
            sig_hash = 0
            try:
                sig_pair, sig_type = parse_signature_blob(sig_blob)
                sig_hash = vmc.signature_for_hash_type_f(sig_type, [sig_blob], vmc)
            except ValueError:
                pass
            sig_blobs.append((sig_blob, sig_hash))
    except IndexError:
        pass
    vmc.stack = s
    return (sec_blobs, sig_blobs)

def traceback_f(opcode, data, pc, vmc):
    if opcode in (self.OP_CHECKSIG, self.OP_CHECKSIGVERIFY):
        blobs_for_sig_ops.append(self._handle_checksig(vmc))
    if opcode in (self.OP_CHECKMULTISIG, self.OP_CHECKMULTISIGVERIFY):
        blobs_for_sig_ops.append(self._handle_checkmultisig(vmc))
    return

def extract_secs(self, tx, tx_in_idx):
    for sec_blobs, sig_and_hash_pairs in self.extract_secs_and_signatures(tx, tx_in_idx):
        for blob in sec_blobs:
            yield blob

def extract_signatures(self, tx, tx_in_idx):
    for sec_blobs, sig_and_hash_pairs in self.extract_secs_and_signatures(tx, tx_in_idx):
        for sig_blob, sig_hash in sig_and_hash_pairs:
            try:
                sig_pair, sig_type = parse_signature_blob(sig_blob)
                yield (sig_blob, sig_hash)
            except (ValueError, TypeError, UnexpectedDER, ScriptError):
                continue

def extract_secs_and_signatures(self, tx, tx_in_idx):
    """
    List[Tuple[List[bytes], List[Tuple[bytes, SigHashFType]]]
    """
    sc = tx.SolutionChecker(tx)
    tx_context = sc.tx_context_for_idx(tx_in_idx)

    blobs_for_sig_ops = []
    def traceback_f(opcode, data, pc, vmc):
        if opcode in (self.OP_CHECKSIG, self.OP_CHECKSIGVERIFY):
            blobs_for_sig_ops.append(self._handle_checksig(vmc))
        if opcode in (self.OP_CHECKMULTISIG, self.OP_CHECKMULTISIGVERIFY):
            blobs_for_sig_ops.append(self._handle_checkmultisig(vmc))
        return

    try:
        sc.check_solution(tx_context, traceback_f=traceback_f)
    except ScriptError:
        pass

    return blobs_for_sig_ops

def public_pairs_for_script(self, tx, tx_in_idx, generator):
    """
    For a given script, iterate over and pull out public pairs encoded as sec values.
    """
    public_pairs = []
    for sec in self.extract_secs(tx, tx_in_idx):
        try:
            public_pairs.append(sec_to_public_pair(sec, generator))
        except EncodingError:
            pass
    return public_pairs

def public_pairs_signed(self, tx, tx_in_idx):
    signed_by = []

    public_pairs = self.public_pairs_for_script(tx, tx_in_idx, self._generator)

    for signature, sig_hash in self.extract_signatures(tx, tx_in_idx):
        sig_pair, sig_type = parse_signature_blob(signature)

        for public_pair in public_pairs:
            if self._generator.verify(public_pair, sig_hash, sig_pair):
                signed_by.append((public_pair, sig_pair, sig_type))
    return signed_by

