    URL = "%s/tx/send" % self.base_url
    try:
        d = urlopen(URL, data=data).read()
        return d
    except request.HTTPError as err:
        if err.code == 400:
            raise ValueError(err.readline())
        raise err

def parse(class_, f, allow_segwit=None):
    """Parse a Bitcoin transaction Tx.

    :param f: a file-like object that contains a binary streamed transaction
    :param allow_segwit: (optional) set to True to allow parsing of segwit transactions.
        The default value is defined by the class variable ALLOW_SEGWIT
    """
    if allow_segwit is None:
        allow_segwit = class_.ALLOW_SEGWIT
    version, = parse_struct("L", f)
    v1 = ord(f.read(1))
    is_segwit = allow_segwit and (v1 == 0)
    v2 = None
    if is_segwit:
        flag = f.read(1)
        if flag == b'\0':
            raise ValueError("bad flag in segwit")
        if flag == b'\1':
            v1 = None
        else:
            is_segwit = False
            v2 = ord(flag)
    count = parse_satoshi_int(f, v=v1)
    txs_in = []
    for i in range(count):
        txs_in.append(class_.TxIn.parse(f))
    count = parse_satoshi_int(f, v=v2)
    txs_out = []
    for i in range(count):
        txs_out.append(class_.TxOut.parse(f))

    if is_segwit:
        for tx_in in txs_in:
            stack = []
            count = parse_satoshi_int(f)
            for i in range(count):
                stack.append(parse_satoshi_string(f))
            tx_in.witness = stack
    lock_time, = parse_struct("L", f)
    return class_(version, txs_in, txs_out, lock_time)

def paths_for_hash(self, hash):
    name = b2h_rev(hash)
    for base_dir in self.read_only_paths:
        p = os.path.join(base_dir, "%s_tx.bin" % name)
        if os.path.exists(p):
            yield p

def get(self, key):
    for path in self.paths_for_hash(key):
        try:
            tx = Tx.parse(open(path, "rb"))
            if tx and tx.hash() == key:
                return tx
        except IOError:
            pass
    for method in self.lookup_methods:
        try:
            tx = method(key)
            if tx and tx.hash() == key:
                self.put(tx)
                return tx
        except Exception:
            pass
    return None

def tx_from_hex(cls, hex_string):
    warnings.simplefilter('always', DeprecationWarning)
    warnings.warn("Call to deprecated function tx_from_hex, use from_hex instead",
                  category=DeprecationWarning, stacklevel=2)
    warnings.simplefilter('default', DeprecationWarning)
    return cls.from_hex(hex_string)

def hash(self, hash_type=None):
    """Return the binary hash for this :class:`Tx` object.

    :param hash_type: (optional) if set, generates a hash specific to a particular type of signature.

    :return: 32 byte long binary blob corresponding to the hash
    """
    s = io.BytesIO()
    self.stream(s, include_witness_data=False)
    if hash_type is not None:
        stream_struct("L", s, hash_type)
    return double_sha256(s.getvalue())

def stream_unspents(self, f):
    self.check_unspents()
    for tx_out in self.unspents:
        if tx_out is None:
            tx_out = self.TxOut(0, b'')
        tx_out.stream(f)

def _check_size_limit(self):
    size = len(self.as_bin())
    if size > self.MAX_TX_SIZE:
        raise ValidationFailureError("size > MAX_TX_SIZE")

def has_witness_data(self):
    """Return a boolean indicating if the transaction has any segwit data."""
    return any(len(tx_in.witness) > 0 for tx_in in self.txs_in)

def w_hash(self):
    """Return the segwit-specific binary hash for this :class:`Tx` object.

    :return: 32 byte long binary blob corresponding to the hash
    """
    return double_sha256(self.as_bin())

def w_id(self):
    """Return the segwit-specific binary hash for this :class:`Tx` object as a hex string.
    Note that this is a ``reversed`` version of :func:`Tx.w_hash <w_hash>`.

    :return: 64 character long hex string corresponding to the hash
    """
    return b2h_rev(self.w_hash())

def dump_header(output, tx):
    tx_bin = stream_to_bytes(tx.stream)
    output.append("Version: %2d  tx hash %s  %d bytes" % (tx.version, tx.id(), len(tx_bin)))
    if tx.has_witness_data():
        output.append("      segwit tx hash %s" % tx.w_id())
    output.append("TxIn count: %d; TxOut count: %d" % (len(tx.txs_in), len(tx.txs_out)))
    if tx.lock_time == 0:
        meaning = "valid anytime"
    elif tx.lock_time < LOCKTIME_THRESHOLD:
        meaning = "valid after block index %d" % tx.lock_time
    else:
        when = datetime.datetime.utcfromtimestamp(tx.lock_time)
        meaning = "valid on or after %s utc" % when.isoformat()
    output.append("Lock time: %d (%s)" % (tx.lock_time, meaning))
    output.append("Input%s:" % ('s' if len(tx.txs_in) != 1 else ''))

def _check_tx_inout_count(self):
    if not self.txs_out:
        raise ValidationFailureError("txs_out = []")
    if not self.is_coinbase() and not self.txs_in:
        raise ValidationFailureError("txs_in = []")

def _check_txs_out(self):
    # Check for negative or overflow output values
    nValueOut = 0
    for tx_out in self.txs_out:
        if tx_out.coin_value < 0 or tx_out.coin_value > self.MAX_MONEY:
            raise ValidationFailureError("tx_out value negative or out of range")
        nValueOut += tx_out.coin_value
        if nValueOut > self.MAX_MONEY:
            raise ValidationFailureError("tx_out total out of range")

def _check_txs_in(self):
    # Check for duplicate inputs
    if [x for x in self.txs_in if self.txs_in.count(x) > 1]:
        raise ValidationFailureError("duplicate inputs")
    if (self.is_coinbase()):
        if not (2 <= len(self.txs_in[0].script) <= 100):
            raise ValidationFailureError("bad coinbase script size")
    else:
        refs = set()
        for tx_in in self.txs_in:
            if tx_in.previous_hash == ZERO32:
                raise ValidationFailureError("prevout is null")
            pair = (tx_in.previous_hash, tx_in.previous_index)
            if pair in refs:
                raise ValidationFailureError("spendable reused")
            refs.add(pair)

def bad_solution_count(self, *args, **kwargs):
    if self.is_coinbase():
        return 0
    return super(Tx, self).bad_solution_count(*args, **kwargs)

def missing_unspent(self, idx):
    if self.is_coinbase():
        return True
    if len(self.unspents) <= idx:
        return True
    return self.unspents[idx] is None

def missing_unspents(self):
    if self.is_coinbase():
        return False
    return (len(self.unspents) != len(self.txs_in) or
            any(self.missing_unspent(idx) for idx, tx_in in enumerate(self.txs_in)))

def check_unspents(self):
    if self.missing_unspents():
        raise ValueError("wrong number of unspents. Call unspents_from_db or set_unspents.")

def validate_tx(tx, tx_db, network):
    if not tx.txs_out:
        return
    if tx.missing_unspents():
        print("\n** can't validate transaction as source transactions missing", file=sys.stderr)
    else:
        try:
            if tx_db is None:
                tx_db = create_tx_db(network)
            tx.validate_unspents(tx_db)
            print('all incoming transaction values validated')
        except BadSpendableError as ex:
            print("\n**** ERROR: FEES INCORRECTLY STATED: %s" % ex.args[0], file=sys.stderr)
        except Exception as ex:
            print("\n*** can't validate source transactions as untampered: %s" %
                  ex.args[0], file=sys.stderr)

def __repr__(self):
    return "Tx [%s] (v:%d) [%s] [%s]" % (
        self.id(), self.version, ", ".join(str(t) for t in self.txs_in),
        ", ".join(str(t) for t in self.txs_out))

def __str__(self):
    return '%s<%s mbtc "%s">' % (
        self.__class__.__name__,
        satoshi_to_mbtc(self.coin_value),
        BitcoinScriptTools.disassemble(self.script)
    )

def unspents_from_db(self, tx_db, ignore_missing=False):
    unspents = []
    for tx_in in self.txs_in:
        if tx_in.is_coinbase():
            unspents.append(None)
            continue
        tx = tx_db.get(tx_in.previous_hash)
        if tx and tx.hash() == tx_in.previous_hash:
            unspents.append(tx.txs_out[tx_in.previous_index])
        elif ignore_missing:
            unspents.append(None)
        else:
            raise KeyError(
                "can't find tx_out for %s:%d" % (b2h_rev(tx_in.previous_hash), tx_in.previous_index))
    self.unspents = unspents

def dump_signatures_hex(tx, network):
    sigs = []
    for _, tx_in in enumerate(tx.txs_in):
        sigs.extend(network.who_signed.extract_signatures(tx, _))
    if len(sigs):
        print("SIGNATURES")
    for sig in sigs:
        print(b2h(sig[0]))

def dump_secs_hex(tx, network):
    sec_key_list = []
    for _, tx_in in enumerate(tx.txs_in):
        sec_key_list.extend(network.who_signed.extract_secs(tx, _))
    if len(sec_key_list):
        print("SECS")
    for sec in sec_key_list:
        print(b2h(sec))

def dump_inputs(tx, network):
    for _, tx_out in enumerate(tx.unspents):
        if tx_out:
            print("%d: %s %s" % (_, tx_out.coin_value, network.script.disassemble(tx_out.script)))
        else:
            print("%d: (missing spendable)" % _)

def tx(args, parser):
    (network, txs, spendables, payables, keychain, tx_db, warning_spendables) = parse_context(args, parser)

    for tx in txs:
        if tx.missing_unspents() and (args.augment or tx_db):
            if tx_db is None:
                tx_db = create_tx_db(network)
            tx.unspents_from_db(tx_db, ignore_missing=True)

    # build p2sh_lookup
    warnings = parse_scripts(args, keychain)
    for w in warnings:
        print(w)

    tx = generate_tx(network, txs, spendables, payables, args)

    signature_hints = [h2b(sig) for sig in (args.signature or [])]
    sec_hints = network.tx.solve.build_sec_lookup([h2b(sec) for sec in (args.sec or [])])

    is_fully_signed = do_signing(tx, keychain, keychain, sec_hints, signature_hints, network)

    include_unspents = not is_fully_signed

    if args.dump_signatures or args.dump_secs:
        if args.dump_signatures:
            dump_signatures_hex(tx, network)

        if args.dump_secs:
            dump_secs_hex(tx, network)

        return

    print_output(tx, include_unspents, args.output_file, args.show_unspents, network,
                 args.verbose_signature, args.disassemble, args.trace, args.pdb)

    tx_db = cache_result(tx, tx_db, args.cache, network)

    tx_db = validate_against_bitcoind(tx, tx_db, network, args.bitcoind_url)

    if args.dump_inputs:
        dump_inputs(tx, network)

    if not args.show_unspents:
        tx_db = validate_tx(tx, tx_db, network)

    # print warnings
    if tx_db:
        for m in [tx_db.warning_tx_cache, tx_db.warning_tx_for_tx_hash]:
            if m:
                print("warning: %s" % m, file=sys.stderr)
    if warning_spendables:
        print("warning: %s" % warning_spendables, file=sys.stderr)

def stream(self, f, as_spendable=False):
    super(Spendable, self).stream(f)
    if as_spendable:
        stream_struct("#LIbI", f, self.previous_hash, self.previous_index,
                      self.block_index_available, bool(self.does_seem_spent), self.block_index_spent)

def as_bin(self, as_spendable=False):
    """Return the txo as binary."""
    f = io.BytesIO()
    self.stream(f, as_spendable=as_spendable)
    return f.getvalue()

def from_bin(cls, blob):
    f = io.BytesIO(blob)
    return cls.parse(f)

def dump_inputs(output, tx, network, verbose_signature, traceback_f, disassembly_level):
    for idx, tx_in in enumerate(tx.txs_in):
        if tx.is_coinbase():
            output.append("%4d: COINBASE  %12.5f m%s" % (idx, satoshi_to_mbtc(tx.total_in()), network.symbol))
            continue
        suffix = ""
        if tx.missing_unspent(idx):
            tx_out = None
            address = tx_in.address(address_api=network.address)
        else:
            tx_out = tx.unspents[idx]
            sig_result = " sig ok" if tx.is_solution_ok(idx, traceback_f=traceback_f) else " BAD SIG"
            suffix = " %12.5f m%s %s" % (satoshi_to_mbtc(tx_out.coin_value), network.symbol, sig_result)
            address = network.address.for_script(tx_out.puzzle_script())
        t = "%4d: %34s from %s:%-4d%s" % (idx, address, b2h_rev(tx_in.previous_hash),
                                          tx_in.previous_index, suffix)
        output.append(t.rstrip())
        if disassembly_level > 0:
            dump_disassembly(output, tx, idx, network.annotate)

        if verbose_signature:
            dump_signatures(output, tx, tx_in, tx_out, idx, network, traceback_f)

def dump_disassembly(output, tx, tx_in_idx, annotate):
    for (pre_annotations, pc, opcode, instruction, post_annotations) in \
            annotate.annotate_scripts(tx, tx_in_idx):
        for l in pre_annotations:
            output.append("           %s" % l)
        if 1:
            output.append("    %4x: %02x  %s" % (pc, opcode, instruction))
        for l in post_annotations:
            output.append("           %s" % l)

def dump_signatures(output, tx, tx_in, tx_out, idx, network, traceback_f):
    sc = tx.SolutionChecker(tx)
    signatures = [parse_signature_blob(blob) + (sig_hash, ) for blob, sig_hash in network.who_signed.extract_signatures(tx, idx)]
    if signatures:
        sig_types_identical = (
            tuple(zip(*signatures))[1].count(signatures[0][1]) == len(signatures))
        i = 1 if len(signatures) > 1 else ''
        for sig_pair, sig_type, sig_hash in signatures:
            output.append("      r{0}: {1:#x}\n      s{0}: {2:#x}".format(i, *sig_pair))
            if not sig_types_identical and tx_out:
                output.append("      z{}: {:#066x} {}".format(i, sig_hash,
                              network.annotate.sighash_type_to_string(sig_type)))
            if i:
                i += 1
        if sig_types_identical and tx_out:
            output.append("      z:{} {:#066x} {}".format(' ' if i else '', sig_hash,
                           network.annotate.sighash_type_to_string(sig_type)))

def dump_tx(output, tx, network, verbose_signature, disassembly_level, do_trace, use_pdb):
    missing_unspents = tx.missing_unspents()
    traceback_f = make_trace_script(network, output, do_trace, use_pdb)

    dump_header(output, tx)

    dump_inputs(output, tx, network, verbose_signature, traceback_f, disassembly_level)

    output.append("Output%s:" % ('s' if len(tx.txs_out) != 1 else ''))
    for idx, tx_out in enumerate(tx.tx_outs_as_spendable()):
        amount_mbtc = satoshi_to_mbtc(tx_out.coin_value)
        address = network.address.for_script(tx_out.puzzle_script()) or "(unknown)"
        output.append("%4d: %34s receives %12.5f m%s" % (idx, address, amount_mbtc, network.symbol))
        if disassembly_level > 0:
            for (pre_annotations, pc, opcode, instruction, post_annotations) in \
                    network.annotate.annotate_spendable(tx.__class__, tx_out):
                for l in pre_annotations:
                    output.append("           %s" % l)
                if 1:
                    output.append("    %4x: %02x  %s" % (pc, opcode, instruction))
                for l in post_annotations:
                    output.append("           %s" % l)

    dump_footer(network, output, tx, missing_unspents)

def message_about_tx_cache_env():
    if main_cache_dir() is None:
        return "consider setting environment variable PYCOIN_CACHE_DIR=~/.pycoin_cache to"\
               " cache transactions fetched via web services"

def main_cache_dir():
    p = os.getenv("PYCOIN_CACHE_DIR")
    if p:
        p = os.path.expanduser(p)
    return p

def tx_writable_cache_dir():
    p = main_cache_dir()
    if p:
        p = os.path.join(main_cache_dir(), "txs")
    return p

def parse_parts(tx_class, arg, spendables, payables, network):
    parts = arg.split("/")
    if 4 <= len(parts) <= 7:
        # spendable
        try:
            spendables.append(tx_class.Spendable.from_text(arg))
            return True
        except Exception:
            pass

    if len(parts) == 2:
        script = script_for_address_or_opcodes(network, parts[0])
        if script is not None:
            payables.append((script, parts[1]))
            return True

def key_found(arg, keychain, key_paths, network):
    try:
        secret = network.parse.secret(arg)
        if secret:
            # TODO: check network
            keychain.add_secrets([secret])
            keychain.add_key_paths(secret, subpaths_for_path_range(key_paths))
            return True
    except Exception:
        pass

    return False

def script_for_address_or_opcodes(network, text):
    try:
        script = network.contract.for_address(text)
        if script:
            return script
    except Exception:
        pass
    try:
        return network.script.compile(text)
    except Exception:
        pass

def parse_context(args, parser):
    network = network_for_netcode(args.network)
    tx_class = network.tx

    # defaults

    spendables = []
    payables = []

    # we create the tx_db lazily
    tx_db = None

    if args.db:

        try:
            txs = [tx_class.from_hex(tx_hex) for tx_hex in args.db or []]
        except Exception:
            parser.error("can't parse ")

        the_ram_tx_db = dict((tx.hash(), tx) for tx in txs)
        if tx_db is None:
            tx_db = create_tx_db(network)
        tx_db.lookup_methods.append(the_ram_tx_db.get)

    txs = []

    if args.coinbase:
        coinbase_tx = build_coinbase_tx(network, args.coinbase)
        txs.append(coinbase_tx)

    keychain = network.keychain(sqlite3.connect(args.keychain))

    # there are a few warnings we might optionally print out, but only if
    # they are relevant. We don't want to print them out multiple times, so we
    # collect them here and print them at the end if they ever kick in.

    warning_spendables = None

    for arg in args.argument:
        tx, tx_db = parse_tx(tx_class, arg, parser, tx_db, network)
        if tx:
            txs.append(tx)
            continue

        if key_found(arg, keychain, args.key_paths, network):
            continue

        if parse_parts(tx_class, arg, spendables, payables, network):
            continue

        payable = script_for_address_or_opcodes(network, arg)
        if payable is not None:
            payables.append((payable, 0))
            continue

        parser.error("can't parse %s" % arg)

    parse_private_key_file(args, keychain, network)

    if args.fetch_spendables:
        warning_spendables = message_about_spendables_for_address_env(args.network)
        for address in args.fetch_spendables:
            spendables.extend(spendables_for_address(address, args.network))

    return (network, txs, spendables, payables, keychain, tx_db, warning_spendables)

def put(self, tx):
    name = b2h_rev(tx.hash())
    if self.writable_cache_path:
        try:
            path = os.path.join(self.writable_cache_path, "%s_tx.bin" % name)
            with open(path, "wb") as f:
                tx.stream(f)
        except IOError:
            pass

def __setitem__(self, key, val):
    if val.hash() != key:
        raise ValueError("bad key %s for %s" % (b2h_rev(key), val))
    self.put(val)

def cache_result(tx, tx_db, cache, network):
    if cache:
        if tx_db is None:
            tx_db = create_tx_db(network)
        tx_db.put(tx)
    return tx_db

def bitcoin_rpc_init(match, netcode):
    username, password, hostname, port = match.group("user", "password", "hostname", "port")
    return BitcoindProvider("http://%s:%s@%s:%s" % (username, password, hostname, port))

def make_trace_script(network, output, do_trace, use_pdb):
    if not (do_trace or use_pdb):
        return None

    def trace_script(opcode, data, pc, vmc):
        output.append("stack: [%s]" % ' '.join(b2h(s) for s in vmc.stack))
        if len(vmc.altstack) > 0:
            output.append("altstack: %s" % vmc.altstack)
        output.append("condition stack: %s" % vmc.conditional_stack)
        output.append("%3d : %02x  %s" % (
            vmc.pc, opcode, network.script.disassemble_for_opcode_data(opcode, data)))
        if use_pdb:
            for line in output:
                print(line)
            output[:] = []
            import pdb
            pdb.set_trace()
    return trace_script

def trace_script(opcode, data, pc, vmc):
    output.append("stack: [%s]" % ' '.join(b2h(s) for s in vmc.stack))
    if len(vmc.altstack) > 0:
        output.append("altstack: %s" % vmc.altstack)
    output.append("condition stack: %s" % vmc.conditional_stack)
    output.append("%3d : %02x  %s" % (
        vmc.pc, opcode, network.script.disassemble_for_opcode_data(opcode, data)))
    if use_pdb:
        for line in output:
            print(line)
        output[:] = []
        import pdb
        pdb.set_trace()

def range_int(min, max, name):

    def cast(v):
        v = int(v)
        if not (min <= v <= max):
            raise ValueError()
        return v

    cast.__name__ = name
    return cast

def parse_locktime(s):
    s = re.sub(r"[ ,:\-]+", r"-", s)
    for fmt1 in ["%Y-%m-%dT", "%Y-%m-%d", "%b-%d-%Y", "%b-%d-%y", "%B-%d-%Y", "%B-%d-%y"]:
        for fmt2 in ["T%H-%M-%S", "T%H-%M", "-%H-%M-%S", "-%H-%M", ""]:
            fmt = fmt1 + fmt2
            try:
                when = datetime.datetime.strptime(s, fmt)
                if when < EARLIEST_DATE:
                    raise ValueError("invalid date: must be after %s" % EARLIEST_DATE)
                return calendar.timegm(when.timetuple())
            except ValueError:
                pass
    return int(s)

def parse_fee(fee):
    if fee in ["standard"]:
        return fee
    return int(fee)

def cast(v):
    v = int(v)
    if not (min <= v <= max):
        raise ValueError()
    return v

def parse_script_index_hex(input):
    index_s, opcodes = input.split("/", 1)
    index = int(index_s)
    return (index, h2b(opcodes))

def parse_scripts(args, keychain):
    warnings = []

    for p2s in args.pay_to_script or []:
        try:
            keychain.add_p2s_script(h2b(p2s))
        except Exception:
            warnings.append("warning: error parsing pay-to-script value %s" % p2s)

    hex_re = re.compile(r"[0-9a-fA-F]+")
    for f in args.pay_to_script_file or []:
        count = 0
        for l in f:
            try:
                m = hex_re.search(l)
                if m:
                    p2s = m.group(0)
                    keychain.add_p2s_script(h2b(p2s))
                    count += 1
            except Exception:
                warnings.append("warning: error parsing pay-to-script file %s" % f.name)
        if count == 0:
            warnings.append("warning: no scripts found in %s" % f.name)
    keychain.commit()
    return warnings

def parse_arg(arg, force_b58):
    is_hex_input = False
    blob = None
    if not force_b58:
        try:
            blob = h2b(arg)
            is_hex_input = True
        except Exception:
            pass
    if blob is None:
        try:
            blob = a2b_base58(arg)
        except KeyError:
            pass
    if blob is None:
        raise argparse.ArgumentTypeError("can't parse %s" % arg)
    return blob, is_hex_input

def h2b(h):
    """
    A version of binascii.unhexlify that accepts unicode. This is
    no longer necessary as of Python 3.3. But it doesn't hurt.

    Raises a ValueError on failure (unlike binascii.unhexlify, which
    raises a TypeError in Python 2 and a binascii.Error in Python 3).
    """
    try:
        return binascii.unhexlify(h.encode("ascii"))
    except Exception:
        raise ValueError("h2b failed on %s" % h)

def parse_private_key_file(args, keychain, network):
    wif_re = re.compile(r"[1-9a-km-zA-LMNP-Z]{51,111}")
    # address_re = re.compile(r"[1-9a-kmnp-zA-KMNP-Z]{27-31}")
    for f in args.private_key_file:
        if f.name.endswith(".gpg"):
            f = replace_with_gpg_pipe(args, f)
        for line in f.readlines():
            # decode
            if isinstance(line, bytes):
                line = line.decode("utf8")
            # look for WIFs
            possible_keys = wif_re.findall(line)

            def make_key(x):
                try:
                    return network.parse.secret(x)
                except Exception:
                    return None

            keys = [make_key(x) for x in possible_keys]
            for key in keys:
                if key:
                    keychain.add_secrets([key])
                    keychain.add_key_paths(key, subpaths_for_path_range(args.key_paths))

def make_key(x):
    try:
        return network.parse.secret(x)
    except Exception:
        return None

def from_sec(class_, sec):
    """
    Create a key from an sec bytestream (which is an encoding of a public pair).
    """
    public_pair = sec_to_public_pair(sec, class_._generator)
    return class_(public_pair=public_pair, is_compressed=is_sec_compressed(sec))

def calculate_lock_time_and_version(args, txs):

    # if no lock_time is explicitly set, inherit from the first tx or use default
    lock_time = args.lock_time
    if lock_time is None:
        if txs:
            lock_time = txs[0].lock_time
        else:
            lock_time = DEFAULT_LOCK_TIME

    # if no version is explicitly set, inherit from the first tx or use default
    version = args.transaction_version
    if version is None:
        if txs:
            version = txs[0].version
        else:
            version = DEFAULT_VERSION
    return lock_time, version

def remove_indices(items, indices):
    if indices:
        s = set(indices)
        items = [i for idx, i in enumerate(items) if idx not in s]
    return items

def replace_input_scripts(txs_in, replacements):
    for index, blob in replacements:
        txs_in[index].script = blob

def generate_tx(network, txs, spendables, payables, args):
    txs_in, txs_out, unspents = merge_txs(network, txs, spendables, payables)
    lock_time, version = calculate_lock_time_and_version(args, txs)
    if len(unspents) == len(txs_in):
        unspents = remove_indices(unspents, args.remove_tx_in)
    replace_input_scripts(txs_in, args.replace_input_script)
    txs_in = remove_indices(txs_in, args.remove_tx_in)
    txs_out = remove_indices(txs_out, args.remove_tx_out)
    tx = network.tx(txs_in=txs_in, txs_out=txs_out, lock_time=lock_time, version=version, unspents=unspents)
    fee = args.fee
    try:
        if len(payables) > 0:
            network.tx_utils.distribute_from_split_pool(tx, fee)
    except ValueError as ex:
        print("warning: %s" % ex.args[0], file=sys.stderr)
    return tx

def wif_iter(iters):
    while len(iters) > 0:
        for idx, iter in enumerate(iters):
            try:
                wif = next(iter)
                yield wif
            except StopIteration:
                iters = iters[:idx] + iters[idx+1:]
                break

def ku_output(self):
    for f in [self.ku_output_for_secret_exponent, self.ku_output_for_public_pair, self.ku_output_for_address]:
        for _ in f():
            yield _

def ku_output_for_secret_exponent(self):
    if self._secret_exponent:
        yield ("secret_exponent", '%d' % self._secret_exponent, None)
        yield ("secret_exponent_hex", '%x' % self._secret_exponent, " hex")
        yield ("wif", self.wif(is_compressed=True), None)
        yield ("wif_uncompressed", self.wif(is_compressed=False), " uncompressed")

def gpg_entropy():
    try:
        output = subprocess.Popen(
            ["gpg", "--gen-random", "2", "64"], stdout=subprocess.PIPE).communicate()[0]
        return output
    except OSError:
        sys.stderr.write("warning: can't open gpg, can't use as entropy source\n")
    return b''

def get_entropy():
    entropy = bytearray()
    try:
        entropy.extend(gpg_entropy())
    except Exception:
        print("warning: can't use gpg as entropy source", file=sys.stdout)
    try:
        entropy.extend(open("/dev/random", "rb").read(64))
    except Exception:
        print("warning: can't use /dev/random as entropy source", file=sys.stdout)
    entropy = bytes(entropy)
    if len(entropy) < 64:
        raise OSError("can't find sources of entropy")
    return entropy

def _create_bip32(network):
    max_retries = 64
    for _ in range(max_retries):
        try:
            return network.keys.bip32_seed(get_entropy())
        except ValueError as e:
            continue
    # Probably a bug if we get here
    raise RuntimeError("can't create BIP32 key")

def parse_key(item, networks):
    default_network = networks[0]
    if item == 'create':
        return _create_bip32(default_network)

    if HASH160_RE.match(item):
        # BRAIN DAMAGE: lame hack for now
        item = default_network.address.for_p2pkh(h2b(item))

    item = default_network.str(item)

    for network in networks:
        for f in "hierarchical_key private_key public_key address".split():
            v = getattr(network.parse, f)(item)
            if v:
                return v

    return None

def create_output(item, key, output_key_set, subkey_path=None):
    output_dict = {}
    output_order = []

    def add_output(json_key, value=None, human_readable_key=None):
        if output_key_set and json_key not in output_key_set:
            return
        if human_readable_key is None:
            human_readable_key = json_key.replace("_", " ")
        if value:
            if human_readable_key == "legacy":
                output_dict[json_key.strip()] = value
            else:
                output_dict[json_key.strip().lower()] = value
                output_order.append((json_key.lower(), human_readable_key))

    full_network_name = "%s %s" % (key._network.network_name, key._network.subnet_name)
    add_output("input", item)
    add_output("network", full_network_name)
    add_output("symbol", key._network.symbol)

    if subkey_path:
        add_output("subkey_path", subkey_path)

    for k, v, text in key.ku_output():
        add_output(k, v, text)

    return output_dict, output_order

def add_output(json_key, value=None, human_readable_key=None):
    if output_key_set and json_key not in output_key_set:
        return
    if human_readable_key is None:
        human_readable_key = json_key.replace("_", " ")
    if value:
