def get_best_ripemd160():
    # ubuntu 22 features an openssl without ripemd160, where python gets its
    # implementation from. To top it off, `"ripemd160" in hashlib.algorithms_available`
    # still evaluates to true, so we actually have to try it to see if we'll fail.

    USE_NATIVE = "ripemd160" in hashlib.algorithms_available and not os.getenv(
        "PYCOIN_USE_PYTHON_RIPEMD160"
    )

    if USE_NATIVE:
        try:
            ripemd160_native(b"").digest()
            return ripemd160_native
        except Exception:
            pass

    # stupid Google App Engine hashlib doesn't support ripemd160 for some stupid reason
    # import it from pycrypto. You need to add
    # - name: pycrypto
    #   version: "latest"
    # to the "libraries" section of your app.yaml
    try:
        from Crypto.Hash.RIPEMD import RIPEMD160Hash
    except Exception:

        class RIPEMD160Hash:
            def __init__(self, data):
                self._digest = pycoin.contrib.ripemd160.ripemd160(data)

            def digest(self):
                return self._digest

    return RIPEMD160Hash

def hash160(data):
    """A standard compound hash."""
    return ripemd160(hashlib.sha256(data).digest()).digest()

def _make_parser(streamer, the_struct):
    "Return a function that parses the given structure into a dict"
    struct_items = [s.split(":") for s in the_struct.split()]
    names = [s[0] for s in struct_items]
    types = ''.join(s[1] for s in struct_items)

    def f(message_stream):
        return streamer.parse_as_dict(names, types, message_stream)
    return f

def parse_from_data(message_name, data):
    message_stream = io.BytesIO(data)
    parser = message_parsers.get(message_name)
    if parser is None:
        raise KeyError("unknown message: %s" % message_name)
    d = parser(message_stream)
    post_unpack = message_post_unpacks.get(message_name)
    if post_unpack:
        d = post_unpack(d, message_stream)
    return d

def pack_from_data(message_name, **kwargs):
    the_struct = message_dict[message_name]
    if not the_struct:
        return b''
    f = io.BytesIO()
    the_fields = the_struct.split(" ")
    pairs = [t.split(":") for t in the_fields]
    for name, type in pairs:
        if type[0] == '[':
            streamer.stream_struct("I", f, len(kwargs[name]))
            for v in kwargs[name]:
                if not isinstance(v, (tuple, list)):
                    v = [v]
                streamer.stream_struct(type[1:-1], f, *v)
        else:
            streamer.stream_struct(type, f, kwargs[name])
    return f.getvalue()

