def _to_bytes(v, length, byteorder="big"):
    """This is the same functionality as ``int.to_bytes`` in python 3"""
    return v.to_bytes(length, byteorder=byteorder)

def _from_bytes(bytes, byteorder="big", signed=False):
    """This is the same functionality as ``int.from_bytes`` in python 3"""
    return int.from_bytes(bytes, byteorder=byteorder, signed=signed)

def to_bytes(v, length, byteorder="big"):
    """This is the same functionality as ``int.to_bytes`` in python 3"""
    ba = bytearray()
    for i in range(length):
        mod = v & 0xff
        v >>= 8
        ba.append(mod)
    if byteorder == "big":
        ba.reverse()
    return bytes(ba)

def from_bytes(bytes, byteorder="big", signed=False):
    """This is the same functionality as ``int.from_bytes`` in python 3"""
    if byteorder != "big":
        bytes = reversed(bytes)
    v = 0
    for c in iterbytes(bytes):
        v <<= 8
        v += c
    if signed and byte2int(bytes) & 0x80:
        v = v - (1 << (8*len(bytes)))
    return v

def to_bytes_32(v):
    v = from_long(v, 0, 256, lambda x: x)
    if len(v) > 32:
        raise ValueError("input to to_bytes_32 is too large")
    return ((b'\0' * 32) + v)[-32:]

def from_bytes_32(v):
    if len(v) > 32:
        raise OverflowError("int too big to convert")
    return to_long(256, byte2int, v)[0]

def b2a_base58(s):
    """Convert binary to base58 using BASE58_ALPHABET. Like Bitcoin addresses."""
    v, prefix = to_long(256, lambda x: x, iterbytes(s))
    s = from_long(v, prefix, BASE58_BASE, lambda v: BASE58_ALPHABET[v])
    return s.decode("utf8")

def a2b_base58(s):
    """Convert base58 to binary using BASE58_ALPHABET."""
    v, prefix = to_long(BASE58_BASE, lambda c: BASE58_LOOKUP[c], s.encode("utf8"))
    return from_long(v, prefix, 256, lambda x: x)

def is_hashed_base58_valid(base58):
    """Return True if and only if base58 is valid hashed_base58."""
    try:
        a2b_hashed_base58(base58)
    except EncodingError:
        return False
    return True

