def pop_check_bounds(vm):
    if len(vm[-1]) > 4:
        raise ScriptError("overflow in binop", errno.UNKNOWN_ERROR)
    return vm.pop_int()

def make_bool_bin_op(binop):
    def f(vm):
        v1, v2 = [pop_check_bounds(vm) for i in range(2)]
        vm.append(vm.bool_to_script_bytes(binop(v2, v1)))
    return f

def f(vm):
